import csv,pathlib
root=pathlib.Path(__file__).parent
rows=list(csv.DictReader(open(root/'evidence/metadata-before.csv')))
grains={'AIRCRAFT':'aircraft identified by aircraft_key','AIRCRAFT_TYPE':'aircraft type identified by aircraft_type_key','AIRPORT':'airport identified by airport_key','ANCILLARY_PRODUCT':'ancillary product identified by ancillary_product_key','CAMPAIGN':'campaign identified by campaign_key','CARD_PRODUCT':'card product identified by card_product_key','CARRIER':'carrier identified by carrier_key','CREW_MEMBER':'crew member identified by crew_key','CUSTOMER':'customer identified by customer_key','DATE':'calendar day identified by calendar_date','DELAY_CAUSE':'delay cause identified by delay_cause_key','FARE_PRODUCT':'fare product identified by fare_product_key','ROUTE':'directional route identified by route_key','SALES_CHANNEL':'sales channel identified by sales_channel_key','AIRPORT_DAY_WEATHER':'airport and weather_date','ANCILLARY_SALE':'ancillary sale identified by ancillary_sale_key','BAGGAGE_CLAIM':'baggage claim identified by baggage_claim_key','CARD_ACCOUNT_MONTHLY':'customer, card product, and month_end_date','CARD_APPLICATION':'card application identified by card_application_key','CREW_ASSIGNMENT':'flight and assigned crew member','FLIGHT':'scheduled flight leg identified by flight_key','FLIGHT_CABIN_LOAD':'flight and cabin','LOYALTY_MONTHLY':'customer and month_end_date','MAINTENANCE_EVENT':'maintenance event identified by maintenance_event_key','PARTNER_REMUNERATION_MONTHLY':'card product and month_end_date','PASSENGER_SURVEY':'survey response identified by survey_key','ROUTE_PNL_MONTHLY':'directional route and month_end_date','SERVICE_CASE':'service case identified by service_case_key','TICKET_SEGMENT':'ticket segment identified by ticket_segment_key'}
special={'miles_balance_end':'Loyalty miles balance at month end; a snapshot. Sum across customers within one month, never across months.','status_dollars_ytd':'Year-to-date status dollars; a cumulative snapshot. Do not sum across months.','loyalty_tier':'Customer dimension loyalty tier; use tier_at_month_end for historical monthly loyalty tier.','tier_at_month_end':'Historical loyalty tier at this month end.','booking_date':'Booking creation date. Use for booking-period analysis; flight_date is the travel date.','flight_date':'Travel date of the flight leg. Use for flown/travel-period analysis.','month_end_date':'Month-end reporting date; monthly fact grain.','total_fare':'Ticket total fare including its recorded components; do not assume it equals recognized passenger revenue.','nps_score':'Individual recommendation score. NPS uses valid scores 0–10: 9–10 promoters, 0–6 detractors, 7–8 passive. Do not report AVG(nps_score) as NPS.','passengers_boarded':'Boarded passenger count. Aggregate at the native fact grain; do not multiply through detail joins.','seats_available':'Available seat count at this table grain. Do not sum repeated flight seats from ticket, survey, or case detail.','operating_income':'Recorded route operating income; use route P&L for full operating profitability.','direct_operating_cost':'Recorded direct operating cost; does not imply full operating cost including ownership and overhead.','price_per_mile':'Unit price per loyalty mile sold. Do not sum unit prices; weight by miles sold when averaging.','arrival_on_time_flag':'Recorded arrival punctuality flag. For ordinary arrival punctuality exclude cancelled and diverted flights from numerator and denominator.','description':'Source description of the delay cause; descriptive text, not a quantitative measure.'}
for r in rows:
 t,c=r['Table Name'],r['Column Name']; parts=t.split('_',2); kind=parts[1] if len(parts)>2 else 'HELPER'; subject=parts[2] if len(parts)>2 else 'NUMBERS'
 if not c:
  r['Display Name']=subject.replace('_',' ').title()+({'VW':' — Enriched View','FACT':' — Base Fact','DIM':' — Dimension'}.get(kind,' — Helper'))
  if t=='ZAL_NUMS': desc='Technical number-series helper. Not a business fact; use only for deliberate sequence generation.'
  else:
   desc='One row per '+grains[subject]+'. '
   desc+=('Enriched analytical view with dimension attributes; prefer it for questions within this subject to avoid unnecessary joins. Do not union with or add totals from the corresponding base fact. ' if kind=='VW' else 'Base fact for this subject; the corresponding ZAL_VW view is preferred when descriptive dimensions are needed. ' if kind=='FACT' else 'Lookup dimension; join facts through the matching key with verified many-to-one cardinality. ')
   if kind in ('VW','FACT'): desc+='Aggregate measures at this grain before combining with another fact; never join independent fact detail into additive totals.'
  r['Description']=desc
 else:
  r['Display Name']=c.replace('_',' ').title().replace('Iata','IATA').replace('Nps','NPS').replace('Csat','CSAT').replace('Ytd','YTD')
  desc=special.get(c)
  if not desc:
   if c.endswith('_key'): desc='Identifier for '+c[:-4].replace('_',' ')+'. Use as a key for matching, filtering, or distinct counting; never sum or average.'
   elif c.endswith('_flag'): desc='Recorded '+c[:-5].replace('_',' ')+' indicator. Inspect source values before filtering; aggregate as a rate only with an explicit eligible denominator.'
   elif c.endswith('_ts'): desc=c.replace('_',' ') + '. Source timestamp; timezone semantics must be confirmed before cross-zone time calculations.'
   elif 'date' in c: desc=c.replace('_',' ').capitalize()+'. Preserve its business event meaning when choosing the reporting period.'
   elif c.endswith('_pct'): desc=c.replace('_',' ').capitalize()+'. Percentage/rate; confirm its scale from source values and do not sum.'
   elif c.endswith('_score'): desc=c.replace('_',' ').capitalize()+'. Recorded score; confirm valid range and exclude missing values from averages.'
   else: desc=c.replace('_',' ').capitalize()+' as recorded at this table’s native grain. Preserve units and distinguish measures from descriptive attributes.'
  r['Description']=desc
with open(root/'context/metadata.csv','w') as f:
 w=csv.DictWriter(f,fieldnames=rows[0].keys());w.writeheader();w.writerows(rows)
print('Prepared metadata:',len(rows),'rows;',sum(not r['Column Name'] for r in rows),'tables')
